mapper.select:
SELECT u.id, u.type, u.login_id, u.password, u.fullname, u.gender, u.birthday, u.mobile, u.email, u.address, u.profile_img, u.session_id, u.auto_login_limit, u.wrong_password_count, u.created_at, u.updated_at, u.deleted_at, c.name, le.id as leId, le.completion_status as leCompletionStatus, c.id as courseId, c.name as courseName FROM user u INNER JOIN learner_enrollment le ON u.id = le.user_id LEFT JOIN course c ON le.course_id = c.id LEFT JOIN staff_assignment sa ON le.course_id = sa.course_id LEFT JOIN staff_detail sd ON sa.user_id = sd.user_id WHERE u.type = 'LEARNER' AND ( CASE WHEN (sd.position = 'GENERAL_MANAGER') THEN 1=1 WHEN (sd.position IN ('COURSE_HEAD', 'FULLTIME_INSTRUCTOR')) THEN sa.user_id = #{loginUserId} ELSE 1=0 END )
AND u.fullname LIKE CONCAT('%', #{pageUserReqDTO.keyword}, '%')
AND c.is_in_progress = #{isInProgress}
AND c.id = #{courseId}
ORDER BY ${pageUserReqDTO.orderBy} ${pageUserReqDTO.orderDirection}
LIMIT #{pageUserReqDTO.offset}, #{pageUserReqDTO.pageSize}

SELECT le.id AS leId, le.completion_status AS leCompletionStatus, u.id AS userId, u.fullname AS userFullname, u.birthday AS userBirthday, u.mobile AS userMobile, u.email AS userEmail, u.address AS userAddress, u.gender AS userGender, u.profile_img AS userProfileImg, es.id AS esId, es.is_counseling_received AS esIsCounselingReceived, es.counseling_details AS esCounselingDetails, es.employment_status AS esEmploymentStatus, es.company_name AS esCompanyName, es.company_phone AS esCompanyPhone, es.company_address AS esCompanyAddress, c.id AS courseId, c.is_in_progress AS courseIsInProgress, c.name AS courseName, c.lesson_start_time AS courseLessonStartTime, c.lesson_end_time AS courseLessonEndTime,
( SELECT us.fullname FROM staff_assignment sa_instructor INNER JOIN staff_detail sd_instructor ON sa_instructor.user_id = sd_instructor.user_id INNER JOIN user us ON sa_instructor.user_id = us.id WHERE sa_instructor.course_id = c.id AND sd_instructor.position = 'FULLTIME_INSTRUCTOR' LIMIT 1 ) AS courseFulltimeInstructor
FROM learner_enrollment le INNER JOIN user u ON le.user_id = u.id INNER JOIN course c ON le.course_id = c.id LEFT JOIN employment_support es ON le.id = es.learner_enrollment_id WHERE
AND u.fullname LIKE CONCAT('%', #{pageLearnerReqDTO.keyword}, '%')
AND c.is_in_progress = #{isInProgress}
AND c.id = #{courseId}
AND le.id = #{leId}
GROUP BY le.id ORDER BY u.${pageLearnerReqDTO.orderBy} ${pageLearnerReqDTO.orderDirection}
LIMIT #{pageLearnerReqDTO.offset}, #{pageLearnerReqDTO.pageSize}

mapper.sql:
(
u.id = #{loginUserId}
OR EXISTS ( 
SELECT 1 FROM staff_detail
WHERE user_id = #{loginUserId}
AND position = 'GENERAL_MANAGER'
)
OR EXISTS ( 
SELECT 1
FROM staff_assignment sa_auth
INNER JOIN staff_detail sd_auth ON sa_auth.user_id = sd_auth.user_id
WHERE
sa_auth.course_id = le.course_id  
AND sd_auth.position IN ('COURSE_HEAD', 'FULLTIME_INSTRUCTOR')
AND sa_auth.user_id = #{loginUserId}
)
)
